-- Prepend team-fixtures.sql, or run after the proposed migration inside a rollback transaction.
reset role;
update public.profiles set department_id=current_setting('test.department')::uuid where id=current_setting('test.admin')::uuid;
update public.departments set manager_id=current_setting('test.manager')::uuid where id=current_setting('test.department')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.admin'),true);
do $$declare r uuid;w uuid;p uuid;j jsonb;t uuid;begin
 j:=public.role_workspace('get');r:=(j->'role'->>'id')::uuid;perform set_config('test.client_role',r::text,true);
 if not (j ? 'readiness') then raise exception 'New wrapper not reached';end if;
 perform public.role_workspace('profile',r,jsonb_build_object('title','Operations lead','cover_id',current_setting('test.employee')));
 j:=public.role_workspace('save',r,'{"kind":"responsibility","title":"Weekly report","fields":{"details":"Check supplier figures","recurrence":"Weekly","steps":"Review then send","importance":"Critical"},"include_in_handover":true}');w:=(j->>'id')::uuid;perform set_config('test.client_work',w::text,true);
 j:=public.role_workspace('save',r,'{"kind":"document","title":"Private document","fields":{"url":"https://example.invalid/private","details":"Private content"},"include_in_handover":false,"is_private":true}');p:=(j->>'id')::uuid;perform set_config('test.client_private',p::text,true);
 j:=public.role_workspace('save',r,'{"kind":"document","title":"Not included","fields":{"url":"https://example.invalid/excluded"},"include_in_handover":false}');
 j:=public.role_workspace('preview',r);if j::text like '%Private document%' or j::text like '%Not included%' or j::text not like '%Weekly report%' then raise exception 'Preview privacy wrong';end if;
 j:=public.role_workspace('handover',r);if j::text like '%Private document%' or j::text like '%Not included%' then raise exception 'Legacy handover leaks excluded items';end if;
 perform public.role_workspace('note_save',r,'{"body":"My private note","include_in_handover":false}');
 perform public.role_workspace('note_save',r,'{"body":"Included note","include_in_handover":true}');
 j:=public.role_workspace('preview',r);if j::text like '%My private note%' or j::text not like '%Included note%' then raise exception 'Note consent lost';end if;
 begin perform public.role_workspace('save',r,'{"kind":"document","title":"Unsafe","fields":{"url":"https://example.invalid","details":"password: secret"}}');raise exception 'Secret accepted';exception when check_violation then null;end;
 begin perform public.role_workspace('save',r,'{"kind":"responsibility","title":"Missing frequency","fields":{"details":"Work"}}');raise exception 'Missing frequency accepted';exception when check_violation then null;end;
 begin perform public.role_workspace('settings',r,jsonb_build_object('id',w,'kind','responsibility','version',999,'include_in_handover',true));raise exception 'Stale save accepted';exception when serialization_failure then null;end;
 perform public.role_workspace('recurring',r,jsonb_build_object('id',w,'fields',jsonb_build_object('due_date',current_date,'recurrence','Weekly')));
 j:=public.role_workspace('linked_tasks',r,jsonb_build_object('id',w));if jsonb_array_length(j)<>1 then raise exception 'Repeating task was not created';end if;
 perform public.role_workspace('duplicate',r,jsonb_build_object('id',w,'kind','responsibility'));
 perform public.role_workspace('archive',r,jsonb_build_object('id',w,'kind','responsibility'));
 perform public.role_workspace('archive',r,jsonb_build_object('id',w,'kind','responsibility','restore',true));
 j:=public.role_workspace('guide_create',r,jsonb_build_object('expires',now()+interval '1 day'));perform set_config('test.client_guide',j->>'token',true);perform set_config('test.client_share',j->>'id',true);
 j:=public.read_role_guide(current_setting('test.client_guide'));if j::text like '%My private note%' or j::text like '%Private document%' then raise exception 'Share leaks private data';end if;
 t:=gen_random_uuid();
 perform public.handover_workspace('save',t,jsonb_build_object('title','Role inclusion test','role_id',r,'owner_id',auth.uid(),'cover_id',current_setting('test.employee'),'reviewer_id',current_setting('test.manager'),'starts_on',current_date,'ends_on',current_date+1,'sections',jsonb_build_object('priorities','Review report'),'inclusions',jsonb_build_array('work','documents','notes'),'items','[]'::jsonb));
 j:=public.handover_workspace('populate',t,'{}');if j::text like '%Private document%' or j::text like '%Not included%' or j::text like '%My private note%' or j::text not like '%Included note%' then raise exception 'Handover populate ignored inclusion: %',j;end if;
 j:=public.role_workspace('get',r);
 if j->'readiness'->>'left'<>'0' then raise exception 'Complete role not ready: %',j->'readiness';end if;
 j:=public.role_workspace('suggestions',r);if not(j?'work' and j?'contacts') then raise exception 'Rule suggestions unavailable';end if;
 perform public.role_workspace('summary_source',r);
 perform public.role_workspace('templates_save',r,'{"name":"Operations template"}');
 perform public.role_workspace('pass_role',r,jsonb_build_object('recipient',current_setting('test.employee')));
 perform public.role_workspace('review_request',r);j:=public.role_workspace('get',r);perform set_config('test.client_review',j->'review'->>'id',true);
end$$;
reset role;
insert into private.myday_notifications(owner_id,company_id,task_id,title,body,created_at)
select a.owner_id,a.company_id,a.id,v.title,v.body,v.at from public.actions a cross join (values('Old task update','Old',now()-interval '1 minute'),('Latest task update','Latest',now()))v(title,body,at) where a.owner_id=current_setting('test.admin')::uuid and a.stable_role_item_id=current_setting('test.client_work')::uuid;
set local role authenticated;
do $$declare j jsonb;begin j:=public.myday_suite('notifications');if jsonb_array_length(j->'rows')<>1 or j->'rows'->0->>'title'<>'Latest task update' then raise exception 'Notification duplication: %',j;end if;end$$;
select set_config('request.jwt.claim.sub',current_setting('test.manager'),true);
do $$declare r uuid:=current_setting('test.client_role')::uuid;j jsonb;begin
 j:=public.role_workspace('get',r);if j::text like '%Private document%' or j::text like '%My private note%' or j::text like '%Not included%' then raise exception 'Manager sees excluded content';end if;
 if has_function_privilege('authenticated','private.role_workspace_previous(text,uuid,jsonb)','EXECUTE') then raise exception 'Old RPC bypass callable';end if;
 if exists(select 1 from public.role_items where id=current_setting('test.client_private')::uuid) then raise exception 'Direct RLS private item leak';end if;
 begin perform public.role_workspace('save',r,'{"kind":"responsibility","title":"Denied","fields":{"recurrence":"Weekly"}}');raise exception 'Manager edited directly';exception when insufficient_privilege then null;end;
 perform public.role_workspace('review_response',r,jsonb_build_object('id',current_setting('test.client_review'),'status','approved'));
 j:=public.role_workspace('team_readiness',r);if j::text like '%supplier figures%' then raise exception 'Team readiness exposes contents';end if;
end$$;
select set_config('request.jwt.claim.sub',current_setting('test.other_admin'),true);
do $$begin begin perform public.role_workspace('get',current_setting('test.client_role')::uuid);raise exception 'Cross tenant read';exception when insufficient_privilege then null;end;end$$;
select set_config('request.jwt.claim.sub',current_setting('test.employee'),true);
do $$declare j jsonb;r uuid;draft uuid;begin
 j:=public.role_workspace('get');r:=(j->'role'->>'id')::uuid;draft:=(j->'incoming'->0->>'id')::uuid;if draft is null then raise exception 'Successor draft missing';end if;
 if jsonb_array_length(j->'items')<>0 then raise exception 'Draft was accepted automatically';end if;
 perform public.role_workspace('incoming_accept',r,jsonb_build_object('id',draft));
 j:=public.role_workspace('get',r);if jsonb_array_length(j->'items')=0 then raise exception 'Draft acceptance missing';end if;
 if j::text like '%Private document%' or j::text like '%My private note%' then raise exception 'Successor inherited private data';end if;
end$$;
select set_config('request.jwt.claim.sub',current_setting('test.admin'),true);
select public.role_workspace('guide_revoke',current_setting('test.client_role')::uuid,jsonb_build_object('id',current_setting('test.client_share')));
do $$begin begin perform public.read_role_guide(current_setting('test.client_guide'));raise exception 'Revoked guide readable';exception when insufficient_privilege then null;end;end$$;
reset role;
select 'My role privacy, readiness, versioning, recurring task, manager review, role draft, guide and tenant tests passed' result;
rollback;
